#[AsCommand(name: 'app:backup:verify', description: 'Restore the latest backup and verify it')]
#[AsCronTask('0 5 * * 0')]
final class BackupVerifyCommand extends Command
{
    protected function execute(InputInterface $in, OutputInterface $out): int
    {
        $start = microtime(true);
        (new Process(['pgbackrest', '--stanza=main', '--delta', '--type=immediate',
            '--pg1-path='.$this->scratchDir, 'restore']))->setTimeout(7200)->mustRun();
        (new Process(['pg_ctl', '-D', $this->scratchDir, '-w', 'start',
            '-o', '-p 5433 -c archive_mode=off']))->mustRun();
        $secs = (int) (microtime(true) - $start);

        $orders = (int) $this->scratch->fetchOne('SELECT count(*) FROM orders');
        $raw = $this->scratch->fetchOne('SELECT max(created_at) FROM orders');
        $latest = new \DateTimeImmutable($raw);
        if ($orders < $this->minOrders || $latest < new \DateTimeImmutable('-26 hours')) {
            $out->writeln('<error>restore worked, but data is too small or old</error>');

            return Command::FAILURE;     // the alert fires from here
        }
        $out->writeln("restore OK, took {$secs}s");   // this is the real RTO

        return Command::SUCCESS;
    }
}

protected function configure(): void
{
    $this->addOption('dry-run', null, InputOption::VALUE_NONE, 'Only count and show')
        ->addOption('rate', null, InputOption::VALUE_REQUIRED, 'How many per second', '20')
        ->addOption('job', null, InputOption::VALUE_REQUIRED, 'Checkpoint name', 'replay');
}

protected function execute(InputInterface $in, OutputInterface $out): int
{
    $job = $in->getOption('job');
    $dry = (bool) $in->getOption('dry-run');
    $pause = intdiv(1_000_000, max(1, (int) $in->getOption('rate')));
    $after = $this->checkpoints->get($job);
    $done = 0;

    while ($batch = $this->failed->after($after, 100)) {
        foreach ($batch as $e) {
            if (!$dry) {
                $this->bus->dispatch(
                    new ProcessPayment($e->id, $e->userId, $e->amount),
                    [new TransportNamesStamp('replay')],    // its own transport
                );
                usleep($pause);                  // slow: capped per second
            }
            $after = $e->id;
            ++$done;
        }
        if (!$dry) {
            $this->checkpoints->save($job, $after);   // done up to here
        }
        $out->writeln("$done done, last id: $after");
    }

    return Command::SUCCESS;
}

CREATE TABLE replay_checkpoint (
  job        text PRIMARY KEY,
  last_id    bigint NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- save the checkpoint (upsert)
INSERT INTO replay_checkpoint (job, last_id) VALUES (:job, :id)
ON CONFLICT (job) DO UPDATE
   SET last_id = EXCLUDED.last_id, updated_at = now();

-- next batch: not OFFSET, but from just after the last id
SELECT id, payload FROM failed_event
 WHERE id > :after AND status = 'failed'
 ORDER BY id LIMIT 100;

#[AsMessageHandler]
public function __invoke(ProcessPayment $m): void
{
    $this->wallet->credit($m->userId, $m->amount);      // arrives twice, credited twice
    $this->mailer->send(new ReceiptEmail($m->userId));  // receipts go out again
}

#[AsMessageHandler]
public function __invoke(ProcessPayment $m): void
{
    $this->db->transactional(function () use ($m): void {
        $new = $this->db->executeStatement(
            'INSERT INTO processed_event (event_id) VALUES (?) ON CONFLICT DO NOTHING',
            [$m->eventId],
        );
        if (1 === $new) {
            $this->wallet->credit($m->userId, $m->amount);   // only the first time
        }
        // the receipt is queued once per event, even if the credit was done earlier
        $this->db->executeStatement(
            'INSERT INTO receipt_outbox (event_id, user_id) VALUES (?, ?)'
            .' ON CONFLICT DO NOTHING',
            [$m->eventId, $m->userId],
        );
    });
}

#[AsPeriodicTask(frequency: '10 seconds', schedule: 'default')]
final readonly class ReceiptSender
{
    public function __invoke(): void
    {
        $rows = $this->db->fetchAllAssociative(
            'SELECT event_id, user_id FROM receipt_outbox
              WHERE sent_at IS NULL ORDER BY event_id LIMIT 50'
        );
        foreach ($rows as $r) {
            $this->mailer->send(new ReceiptEmail($r['user_id']));
            $this->db->executeStatement(
                'UPDATE receipt_outbox SET sent_at = now() WHERE event_id = ?',
                [$r['event_id']],
            );
        }
    }
}

protected function execute(InputInterface $in, OutputInterface $out): int
{
    $expect = (int) $in->getOption('expect');            // the number agreed in review
    $count = (int) $this->db->fetchOne(self::COUNT_SQL);
    $out->writeln("Affected: $count, expected: $expect");

    if ($count !== $expect) {
        $out->writeln('<error>Count mismatch, nothing was changed</error>');

        return Command::FAILURE;
    }
    if ($in->getOption('dry-run')) {
        return Command::SUCCESS;                          // only counting
    }

    $fixed = $this->db->transactional(
        fn () => $this->db->executeStatement(self::FIX_SQL),
    );
    $out->writeln("$fixed fixed; recorded in data_fix_log");

    return Command::SUCCESS;
}
